package com.smartblog.mapper;
import com.smartblog.entity.UserCredential; import org.apache.ibatis.annotations.*;
public interface UserCredentialMapper { @Insert("INSERT INTO user_credentials(user_id,credential_type,secret_hash,status) VALUES(#{userId},#{credentialType},#{secretHash},#{status})") @Options(useGeneratedKeys=true,keyProperty="id") int insert(UserCredential c); @Select("SELECT id,user_id,credential_type,secret_hash,status,create_time,update_time FROM user_credentials WHERE user_id=#{userId} AND credential_type='PASSWORD' AND status=1 LIMIT 1") UserCredential selectActivePasswordByUserId(@Param("userId") Long userId); @Update("UPDATE user_credentials SET secret_hash=#{secretHash},update_time=NOW() WHERE user_id=#{userId} AND credential_type='PASSWORD' AND status=1") int updatePasswordByUserId(@Param("userId") Long userId,@Param("secretHash") String secretHash); }
